// El stock de ejemplo. Se carga una sola vez en la tabla stock.
const stock = [
  { producto: "remera", talle: 'S', cantidad: 4 },
  { producto: "remera", talle: 'M', cantidad: 0 },
  { producto: "remera", talle: 'L', cantidad: 7 },
  { producto: "remera", talle: 'XL', cantidad: 2 },
  { producto: "buzo", talle: 'M', cantidad: 3 },
  { producto: "buzo", talle: 'L', cantidad: 1 },
  { producto: "pantalón", talle: 'M', cantidad: 5 },
  { producto: "campera", talle: 'L', cantidad: 0 },
];

return stock.map(fila => ({ json: fila }));
